<template>
  <main ref="pageRef" class="insight-page">
    <header class="insight-header">
      <div class="header-copy">
        <span class="overline"><Icon name="ph:radio-tower-bold" /> DAILY EDITION</span>
        <h1>见闻</h1>
        <p>从不同的角落，收拢值得读完的文字。</p>
      </div>
      <div class="edition-meta"><span>{{ sourceCount }} 个来源</span><i /><span>{{ totalCount }} 篇收录</span><small v-if="fetchedAt">更新于 {{ relativeDate(fetchedAt) }}</small></div>
    </header>

    <div v-if="newItemsCount" class="new-note" role="status"><Icon name="ph:sparkle-bold" /><span>自上次阅读后，新增 <strong>{{ newItemsCount }}</strong> 篇</span><button type="button" title="标记为已读" @click="dismissNewItems"><Icon name="ph:check-bold" /></button></div>

    <nav class="section-index" aria-label="内容模块">
      <button v-for="section in sections" :key="section.key" type="button" :class="{ active: activeSection === section.key }" @click="selectSection(section.key)"><span class="section-dot" :style="{ background: section.color }" />{{ section.label }}<small v-if="section.count">{{ section.count }}</small></button>
    </nav>

    <section class="edition-grid" aria-live="polite">
      <div v-if="loading && !items.length" class="loading-sheet"><span /><span /><span /></div>
      <div v-else-if="!visibleItems.length" class="empty-sheet"><Icon name="ph:leaf-bold" /><h2>这一辑还没有内容</h2><p>订阅源更新后，文章会自动出现在这里。</p></div>
      <template v-else>
        <div class="date-rail" aria-hidden="true"><span>{{ activeDate }}</span><i /></div>
        <article v-for="(item, index) in visibleItems" :key="item.id" class="edition-entry" :class="{ lead: index === 0, 'has-image': item.image && !brokenImages.has(item.id) }" :style="entryStyle(item, index)" tabindex="0" role="link" @click="openItem(item)" @keydown.enter.prevent="openItem(item)" @keydown.space.prevent="openItem(item)">
          <div class="entry-number">{{ String(index + 1).padStart(2, '0') }}</div>
          <div class="entry-main">
            <header><span class="entry-section"><i :style="{ background: sectionColor(item) }" />{{ sectionLabel(item) }}</span><time :datetime="item.publishedAt" :title="formatDate(item.publishedAt)">{{ relativeDate(item.publishedAt) }}</time></header>
            <h2>{{ item.title }}</h2>
            <p v-if="item.summary || item.content">{{ item.summary || item.content }}</p>
            <figure v-if="item.image && !brokenImages.has(item.id)"><img :src="item.image" :alt="item.title" loading="lazy" decoding="async" @error.stop="brokenImages.add(item.id)" /></figure>
            <footer><span>{{ item.source.name }}</span><span v-if="readingMinutes(item)">{{ readingMinutes(item) }} 分钟阅读</span><Icon name="ph:arrow-up-right-bold" /></footer>
          </div>
        </article>
      </template>
    </section>
    <div ref="loadMoreRef" class="load-more" aria-live="polite"><span v-if="hasMore">{{ loadingMore ? '正在收录更多文章' : '继续向下阅读' }}</span><span v-else-if="visibleItems.length">已抵达这一辑的末尾</span></div>
  </main>
</template>

<script setup lang="ts">
type CircleItem = { id: string; title: string; summary: string; url: string; publishedAt: string; image?: string; categories?: string[]; author?: string; content?: string; source: { name: string; url: string; avatar?: string; rssUrl?: string; section?: string } }
type SectionKey = 'all' | 'thought' | 'news' | 'tech' | 'ai' | 'friends'
const api = useApi(); const router = useRouter(); const pageRef = ref<HTMLElement | null>(null); const loadMoreRef = ref<HTMLElement | null>(null); const loading = ref(true); const loadingMore = ref(false); const items = ref<CircleItem[]>([]); const page = ref(1); const totalPages = ref(1); const totalCount = ref(0); const feedSourceCount = ref(0); const fetchedAt = ref(''); const clock = ref(Date.now()); const brokenImages = reactive(new Set<string>()); const activeSection = ref<SectionKey>('all'); const reading = reactive({ lastSeenAt: '' }); const readingKey = 'corner:circle:reading'
const sectionDefs: Array<{ key: SectionKey; label: string; color: string }> = [{ key: 'all', label: '全部', color: 'var(--c-primary)' }, { key: 'thought', label: '思考', color: '#b06a45' }, { key: 'news', label: '新闻', color: '#3d7fa9' }, { key: 'tech', label: '科技', color: '#2b8b71' }, { key: 'ai', label: 'AI', color: '#8066aa' }, { key: 'friends', label: '友链', color: '#c18a36' }]
const sourceCount = computed(() => feedSourceCount.value || new Set(items.value.map(item => item.source.url)).size); const visibleItems = computed(() => activeSection.value === 'all' ? items.value : items.value.filter(item => sectionFor(item) === activeSection.value)); const activeDate = computed(() => visibleItems.value[0] ? dateLabel(visibleItems.value[0].publishedAt) : ''); const hasMore = computed(() => page.value < totalPages.value); const newItemsCount = computed(() => { if (!reading.lastSeenAt) return 0; const since = Date.parse(reading.lastSeenAt); return Number.isFinite(since) ? items.value.filter(item => Date.parse(item.publishedAt) > since).length : 0 }); const sections = computed(() => sectionDefs.map(section => ({ ...section, count: section.key === 'all' ? totalCount.value : items.value.filter(item => sectionFor(item) === section.key).length })))
function sectionFor(item: CircleItem): SectionKey { if (['thought', 'news', 'tech', 'ai', 'friends'].includes(String(item.source.section))) return item.source.section as SectionKey; const text = `${item.source.name} ${(item.categories || []).join(' ')}`.toLowerCase(); if (/知乎|新闻|hot|日报|早报/.test(text)) return 'news'; if (/ai|人工智能|机器学习|openai/.test(text)) return 'ai'; if (/少数派|sspai|科技|tech/.test(text)) return 'tech'; if (/mrxwlb|onojyun|mobius|思考|随笔|博客/.test(text)) return 'thought'; return 'friends' }
function sectionLabel(item: CircleItem) { return sectionDefs.find(section => section.key === sectionFor(item))?.label || '友链' }; function sectionColor(item: CircleItem) { return sectionDefs.find(section => section.key === sectionFor(item))?.color || 'var(--c-primary)' }; function selectSection(key: SectionKey) { activeSection.value = key; pageRef.value?.scrollTo({ top: 0, behavior: 'smooth' }) }; function openItem(item: CircleItem) { void router.push({ path: '/circle/read', query: { id: item.id } }) }; function entryStyle(item: CircleItem, index: number) { return { '--entry-accent': sectionColor(item), '--entry-order': index } }; function dateLabel(value: string) { const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; const today = new Date(); if (date.toDateString() === today.toDateString()) return 'TODAY'; return new Intl.DateTimeFormat('en-US', { month: 'short', day: '2-digit' }).format(date).toUpperCase() }; function formatDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date) }; function relativeDate(value: string) { const time = new Date(value).getTime(); if (!Number.isFinite(time)) return ''; const minutes = Math.max(0, Math.floor((clock.value - time) / 60000)); if (minutes < 1) return '刚刚'; if (minutes < 60) return `${minutes} 分钟前`; if (minutes < 1440) return `${Math.floor(minutes / 60)} 小时前`; if (minutes < 10080) return `${Math.floor(minutes / 1440)} 天前`; return new Intl.DateTimeFormat('zh-CN', { month: 'short', day: 'numeric' }).format(new Date(time)) }; function readingMinutes(item: CircleItem) { const length = (item.content || item.summary || '').length; return length > 1600 ? Math.max(3, Math.round(length / 700)) : length > 700 ? 2 : 1 }; function dismissNewItems() { reading.lastSeenAt = items.value[0]?.publishedAt || new Date().toISOString(); persistReading() }; function persistReading() { if (typeof window !== 'undefined') localStorage.setItem(readingKey, JSON.stringify({ lastSeenAt: reading.lastSeenAt })) }; function restoreReading() { try { const data = JSON.parse(localStorage.getItem(readingKey) || '{}'); reading.lastSeenAt = typeof data.lastSeenAt === 'string' ? data.lastSeenAt : '' } catch { reading.lastSeenAt = '' } }
async function loadFeed(next = false) { if (next && (!hasMore.value || loadingMore.value)) return; if (next) loadingMore.value = true; else loading.value = true; try { const target = next ? page.value + 1 : 1; const result = await api.get<any>('/circle/feed', { page: target, limit: 20, refresh: next ? undefined : 1 }); const incoming = Array.isArray(result?.items) ? result.items : []; items.value = next ? [...items.value, ...incoming] : incoming; page.value = Number(result?.page) || target; totalPages.value = Number(result?.totalPages) || 1; totalCount.value = Number(result?.total) || items.value.length; feedSourceCount.value = Number(result?.sourceCount) || feedSourceCount.value; fetchedAt.value = String(result?.fetchedAt || '') } finally { loading.value = false; loadingMore.value = false } }
let observer: IntersectionObserver | null = null; let clockTimer: ReturnType<typeof setInterval> | undefined; let feedTimer: ReturnType<typeof setInterval> | undefined
onMounted(() => { restoreReading(); void loadFeed(); clockTimer = setInterval(() => { clock.value = Date.now() }, 60000); feedTimer = setInterval(() => { if (document.visibilityState === 'visible') void loadFeed() }, 300000); nextTick(() => { if (!loadMoreRef.value || !pageRef.value) return; observer = new IntersectionObserver(() => { if (hasMore.value) void loadFeed(true) }, { root: pageRef.value, rootMargin: '420px' }); observer.observe(loadMoreRef.value) }) }); onUnmounted(() => { observer?.disconnect(); if (clockTimer) clearInterval(clockTimer); if (feedTimer) clearInterval(feedTimer); persistReading() }); useHead({ title: '见闻 · 风隅随笔' })
</script>

<style scoped>
.insight-page{flex:1;min-width:0;min-height:0;overflow-y:auto;padding:44px clamp(20px,5vw,80px) 72px;background:var(--c-bg);color:var(--c-text)}.insight-header{display:flex;width:min(1180px,100%);align-items:flex-end;justify-content:space-between;gap:24px;margin:0 auto;padding-bottom:28px;border-bottom:1px solid var(--border)}.overline{display:inline-flex;align-items:center;gap:7px;color:var(--c-primary);font:700 .58rem var(--font-mono);letter-spacing:.16em}.header-copy h1{margin:14px 0 8px;font:680 clamp(2.5rem,7vw,5.6rem)/.95 var(--font-system-rounded);letter-spacing:0}.header-copy p{margin:0;color:var(--c-text-2);font-size:.82rem}.edition-meta{display:flex;align-items:center;gap:10px;padding-bottom:6px;color:var(--c-text-2);font-size:.68rem;white-space:nowrap}.edition-meta i{width:1px;height:15px;background:var(--border)}.edition-meta small{color:var(--c-text-3)}.new-note{display:flex;width:min(1180px,100%);align-items:center;gap:9px;margin:18px auto 0;color:var(--c-primary);font-size:.7rem}.new-note strong{font-variant-numeric:tabular-nums}.new-note button{display:grid;width:26px;height:26px;margin-left:auto;border:1px solid color-mix(in srgb,var(--c-primary) 30%,var(--border));border-radius:50%;background:transparent;color:var(--c-primary);cursor:pointer;place-items:center}.section-index{display:flex;width:min(1180px,100%);gap:6px;margin:30px auto 0;overflow-x:auto;scrollbar-width:none}.section-index::-webkit-scrollbar{display:none}.section-index button{display:inline-flex;flex:0 0 auto;align-items:center;gap:7px;padding:8px 11px;border:0;border-bottom:1px solid transparent;background:transparent;color:var(--c-text-3);cursor:pointer;font:inherit;font-size:.7rem;transition:color .2s,border-color .2s}.section-index button:hover,.section-index button.active{border-bottom-color:var(--c-primary);color:var(--c-text)}.section-dot{width:6px;height:6px;border-radius:50%}.section-index small{color:var(--c-text-3);font:.58rem var(--font-mono)}.edition-grid{position:relative;display:grid;width:min(980px,100%);grid-template-columns:58px minmax(0,1fr);gap:0 20px;margin:34px auto 0}.date-rail{grid-column:1;display:flex;flex-direction:column;align-items:center;padding-top:18px;color:var(--c-text-3);font:.58rem var(--font-mono);letter-spacing:.08em}.date-rail i{width:1px;flex:1;min-height:80px;margin-top:10px;background:linear-gradient(var(--c-primary),transparent);opacity:.45}.edition-entry{grid-column:2;display:grid;grid-template-columns:38px minmax(0,1fr);gap:18px;padding:24px 0 28px;border-bottom:1px solid color-mix(in srgb,var(--border) 72%,transparent);cursor:pointer;animation:entry-in .62s cubic-bezier(.16,1,.3,1) both;animation-delay:min(calc(var(--entry-order)*45ms),320ms)}.entry-number{padding-top:4px;color:color-mix(in srgb,var(--entry-accent) 70%,var(--c-text-3));font:.62rem var(--font-mono)}.entry-main{min-width:0}.entry-main header,.edition-entry footer{display:flex;align-items:center;gap:10px}.entry-main header{justify-content:space-between}.entry-section{display:inline-flex;align-items:center;gap:7px;color:var(--entry-accent);font:700 .58rem var(--font-mono);letter-spacing:.08em;text-transform:uppercase}.entry-section i{width:7px;height:7px;border-radius:50%}.entry-main time{color:var(--c-text-3);font-size:.6rem}.entry-main h2{max-width:760px;margin:10px 0 0;color:var(--c-text);font:650 clamp(1.15rem,2.4vw,1.7rem)/1.3 var(--font-system-rounded);transition:color .2s,transform .28s}.edition-entry:hover h2{color:var(--entry-accent);transform:translateX(4px)}.entry-main p{max-width:670px;margin:10px 0 0;color:var(--c-text-2);font-size:.76rem;line-height:1.85;display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3}.entry-main figure{width:min(100%,680px);aspect-ratio:2.3/1;margin:17px 0 0;overflow:hidden;border-radius:4px;background:var(--c-bg-2)}.entry-main figure img{width:100%;height:100%;object-fit:cover;transition:transform .6s var(--ui-ease-out)}.edition-entry:hover figure img{transform:scale(1.03)}.edition-entry footer{margin-top:18px;color:var(--c-text-3);font-size:.6rem}.edition-entry footer span+span{padding-left:10px;border-left:1px solid var(--border)}.edition-entry footer :deep(svg){margin-left:auto;color:var(--entry-accent)}.edition-entry.lead{padding-top:12px}.edition-entry.lead h2{font-size:clamp(1.7rem,4vw,3.3rem);line-height:1.12}.edition-entry.lead p{font-size:.82rem}.loading-sheet,.empty-sheet{grid-column:1/-1;min-height:300px;display:grid;place-items:center;align-content:center;gap:9px;color:var(--c-text-3);text-align:center}.loading-sheet{display:flex;align-items:center;justify-content:center}.loading-sheet span{width:7px;height:7px;border-radius:50%;background:var(--c-primary);animation:pulse 1s ease-in-out infinite alternate}.loading-sheet span:nth-child(2){animation-delay:.16s}.loading-sheet span:nth-child(3){animation-delay:.32s}.empty-sheet :deep(svg){color:var(--c-primary);font-size:2rem}.empty-sheet h2{margin:4px 0 0;font-size:1rem}.empty-sheet p{margin:0;color:var(--c-text-3);font-size:.7rem}.load-more{display:grid;width:min(980px,100%);min-height:80px;margin:0 auto;place-items:center;color:var(--c-text-3);font-size:.64rem}@keyframes entry-in{from{opacity:0;transform:translateY(16px);filter:blur(2px)}to{opacity:1;transform:none;filter:none}}@keyframes pulse{to{opacity:.25;transform:translateY(-4px)}}
@media (max-width:640px){.insight-page{padding:max(76px,calc(env(safe-area-inset-top) + 58px)) 16px 46px}.insight-header{align-items:flex-start;flex-direction:column;gap:15px;padding-bottom:22px}.header-copy h1{font-size:3.4rem}.edition-meta{flex-wrap:wrap;padding:0;font-size:.62rem;white-space:normal}.edition-meta small{flex-basis:100%}.section-index{margin-top:22px}.edition-grid{grid-template-columns:32px minmax(0,1fr);gap:0 10px;margin-top:22px}.date-rail{font-size:.5rem}.edition-entry{grid-template-columns:24px minmax(0,1fr);gap:10px;padding:20px 0 24px}.entry-number{font-size:.54rem}.entry-main h2{font-size:1.12rem}.edition-entry.lead h2{font-size:1.7rem}.entry-main p{font-size:.7rem;-webkit-line-clamp:4}.entry-main figure{aspect-ratio:1.6/1}.entry-main footer{font-size:.56rem}}@media(prefers-reduced-motion:reduce){.edition-entry,.loading-sheet span,.edition-entry:hover h2,.entry-main figure img{animation:none;transition:none;transform:none}}
</style>
